import React, { useState, useEffect, useCallback } from 'react';
import LoginScreen from './components/auth/LoginScreen/LoginScreen';
import AppLayout from './components/layout/AppLayout/AppLayout';
import Admin5Dashboard from './pages/admin5/Admin5Dashboard/Admin5Dashboard';
import Admin1Dashboard from './pages/admin1/Admin1Dashboard/Admin1Dashboard';
import OngDashboard from './pages/ong/OngDashboard/OngDashboard';
import BeneficiaryDashboard from './pages/beneficiary/BeneficiaryDashboard/BeneficiaryDashboard';
import CreateAdminPage from './pages/admin5/CreateAdminPage/CreateAdminPage';
import ListAdminsPage from './pages/admin5/ListAdminsPage/ListAdminsPage';
import CreateOngPage from './pages/admin5/CreateOngPage/CreateOngPage';
import ListOngsPage from './pages/admin5/ListOngsPage/ListOngsPage';
import ListBeneficiariesPage from './pages/admin5/ListBeneficiariesPage/ListBeneficiariesPage';
import ReportsPage from './pages/admin5/ReportsPage/ReportsPage';
import CreatePrizePage from './pages/admin5/CreatePrizePage/CreatePrizePage';
import ListPrizesPage from './pages/admin5/ListPrizesPage/ListPrizesPage';
import CreateBeneficiaryPage from './pages/ong/CreateBeneficiaryPage/CreateBeneficiaryPage';
import ListOngBeneficiariesPage from './pages/ong/ListOngBeneficiariesPage/ListOngBeneficiariesPage';
import AcceptancePage from './pages/ong/AcceptancePage/AcceptancePage';
import HelpPage from './pages/ong/HelpPage/HelpPage';
import SendSocialProofPage from './pages/beneficiary/SendSocialProofPage/SendSocialProofPage';
import MyBalancePage from './pages/beneficiary/MyBalancePage/MyBalancePage';
import RedeemPrizesPage from './pages/beneficiary/RedeemPrizesPage/RedeemPrizesPage';
import MyRedemptionsPage from './pages/beneficiary/MyRedemptionsPage/MyRedemptionsPage';
import ProfilePage from './pages/shared/ProfilePage/ProfilePage';
import EditProfilePage from './pages/shared/EditProfilePage/EditProfilePage';
import CreateBeneficiaryAdminPage from './pages/admin5/CreateBeneficiaryAdminPage/CreateBeneficiaryAdminPage';
import MySocialProofsPage from './pages/beneficiary/MySocialProofsPage/MySocialProofsPage';
import OngReportsPage from './pages/ong/OngReportsPage/OngReportsPage';


function App() {
  const [currentBeneficiary, setCurrentBeneficiary] = useState(() => {
    try {
      const savedBeneficiary = localStorage.getItem('currentBeneficiary');
      return savedBeneficiary ? JSON.parse(savedBeneficiary) : null;
    } catch (error) {
      console.error("Erro ao ler o localStorage:", error);
      return null;
    }
  });
  const [currentPage, setCurrentPage] = useState('dashboard');

  const login = (beneficiaryData) => {
    localStorage.setItem('currentBeneficiary', JSON.stringify(beneficiaryData));
    setCurrentBeneficiary(beneficiaryData);
    setCurrentPage('dashboard');
  };

  const logout = useCallback(() => {
    localStorage.removeItem('currentBeneficiary');
    setCurrentBeneficiary(null);
  }, []);

  const navigate = (page) => {
    setCurrentPage(page);
  };

  useEffect(() => {
    let inactivityTimer;
    const resetTimer = () => {
      clearTimeout(inactivityTimer);
      inactivityTimer = setTimeout(logout, 900000); // 15 minutos
    };

    if (currentBeneficiary) {
      window.addEventListener('mousemove', resetTimer);
      window.addEventListener('keydown', resetTimer);
      resetTimer();
    }

    return () => {
      clearTimeout(inactivityTimer);
      window.removeEventListener('mousemove', resetTimer);
      window.removeEventListener('keydown', resetTimer);
    };
  }, [currentBeneficiary, logout]);

  const renderPage = () => {
    switch (currentPage) {
        case 'profile': return <ProfilePage beneficiary={currentBeneficiary} onNavigate={navigate} />;
        case 'edit_profile': return <EditProfilePage beneficiary={currentBeneficiary} onNavigate={navigate} />;
    }

    switch (currentBeneficiary?.role) {
      case 'admin5':
        switch (currentPage) {
          case 'dashboard': return <Admin5Dashboard onNavigate={navigate} />;
          case 'create_admin': return <CreateAdminPage />;
          case 'list_admins': return <ListAdminsPage />;
          case 'create_ong': return <CreateOngPage />;
          case 'list_ongs': return <ListOngsPage />;
          case 'create_beneficiary_admin': return <CreateBeneficiaryAdminPage />;
          case 'list_beneficiaries': return <ListBeneficiariesPage />;
          case 'reports': return <ReportsPage />;
          case 'create_prize': return <CreatePrizePage />;
          case 'list_prizes': return <ListPrizesPage />;
          default: return <h1>Página não encontrada para Admin5</h1>;
        }

      case 'admin1':
        switch (currentPage) {
            case 'dashboard': return <Admin1Dashboard onNavigate={navigate} />;
            case 'create_ong': return <CreateOngPage />;
            case 'list_ongs': return <ListOngsPage />;
            case 'create_beneficiary_admin': return <CreateBeneficiaryAdminPage />;
            case 'list_beneficiaries': return <ListBeneficiariesPage />;
            case 'reports': return <ReportsPage />;
            case 'create_prize': return <CreatePrizePage />;
            case 'list_prizes': return <ListPrizesPage />;
            default: return <h1>Página não encontrada para Admin1</h1>;
        }

      case 'ong':
        switch (currentPage) {
            case 'dashboard': return <OngDashboard beneficiary={currentBeneficiary} onNavigate={navigate} />;
            case 'create_beneficiary': return <CreateBeneficiaryPage beneficiary={currentBeneficiary} />;
            case 'list_ong_beneficiaries': return <ListOngBeneficiariesPage beneficiary={currentBeneficiary} />;
            case 'acceptance': return <AcceptancePage beneficiary={currentBeneficiary} />;
            case 'ong_reports': return <OngReportsPage beneficiary={currentBeneficiary} />;
            case 'help': return <HelpPage />;
            default: return <h1>Página não encontrada para ONG</h1>;
        }

      case 'beneficiario': // Alterado de 'beneficiary' para 'beneficiario' para corresponder ao banco de dados
        switch (currentPage) {
            case 'dashboard': return <BeneficiaryDashboard onNavigate={navigate} />;
            case 'send_social_proof': return <SendSocialProofPage beneficiary={currentBeneficiary} />;
            case 'my_social_proofs': return <MySocialProofsPage beneficiary={currentBeneficiary} />;
            case 'my_balance': return <MyBalancePage beneficiary={currentBeneficiary} />;
            case 'redeem_prizes': return <RedeemPrizesPage beneficiary={currentBeneficiary} />;
            case 'my_redemptions': return <MyRedemptionsPage beneficiary={currentBeneficiary} />;
            default: return <h1>Página não encontrada para Beneficiário</h1>;
        }

      default:
        return <h1>Perfil de beneficiário desconhecido.</h1>;
    }
  };

  if (!currentBeneficiary) {
    return <LoginScreen onLoginSuccess={login} />;
  }

  return (
    <AppLayout 
      beneficiary={currentBeneficiary} 
      onNavigate={navigate} 
      onLogout={logout} 
      activePage={currentPage}
    >
      {renderPage()}
    </AppLayout>
  );
}

export default App;
